@* Popup with common emoji buttons *@

<div class="emoji-picker">
    @foreach (var emoji in _emojis)
    {
        <button type="button" class="emoji-picker-btn" @onclick="() => SelectEmoji(emoji)" title="@emoji">
            @emoji
        </button>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public EventCallback<string> OnEmojiSelected { get; set; }

    private static readonly string[] _emojis = ["👍", "❤️", "😂", "🎉", "😮", "🚀"];

    private async Task SelectEmoji(string emoji)
    {
        await OnEmojiSelected.InvokeAsync(emoji);
    }
}

@using sv_8091738486b74e798f1f85cff83429c3.Models

<div class="reaction-bar">
    @foreach (var reaction in Reactions)
    {
        <span class="reaction-badge" title="@string.Join(", ", reaction.Users)">
            @reaction.Emoji @reaction.Users.Count
        </span>
    }
    <div class="reaction-add-wrapper">
        <button type="button" class="reaction-add-btn" @onclick="TogglePicker" title="Add reaction">➕</button>
        @if (_showPicker)
        {
            <EmojiPicker OnEmojiSelected="HandleEmojiSelected" />
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public List<Reaction> Reactions { get; set; } = [];

    [Parameter, EditorRequired]
    public EventCallback<string> OnReact { get; set; }

    private bool _showPicker;

    private void TogglePicker() => _showPicker = !_showPicker;

    private async Task HandleEmojiSelected(string emoji)
    {
        _showPicker = false;
        await OnReact.InvokeAsync(emoji);
    }
}

@using sv_8091738486b74e798f1f85cff83429c3.Models

<div class="channel-item @(_isActive ? "channel-item--active" : "")" @onclick="Select">
    <div class="channel-item-header">
        <span class="channel-item-name"># @Channel.Name</span>
        @if (Channel.UnreadCount > 0)
        {
            <span class="channel-item-badge">@Channel.UnreadCount</span>
        }
    </div>
    <div class="channel-item-desc">@TruncatedDescription</div>
</div>

@code {
    [Parameter, EditorRequired] public Channel Channel { get; set; } = default!;
    [Parameter] public int ActiveChannelId { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnSelected { get; set; }

    private bool _isActive => Channel.Id == ActiveChannelId;

    private string TruncatedDescription =>
        Channel.Description.Length > 50
            ? Channel.Description[..50] + "…"
            : Channel.Description;

    private async Task Select() => await OnSelected.InvokeAsync(Channel.Id);
}

