{"file_text": "<div class="message-input">
    <textarea class="message-input-textarea" @bind="Text" @bind:event="oninput"
              @onkeydown="HandleKeyDown" placeholder="@Placeholder" rows="2"></textarea>
    <button type="button" class="btn btn-primary message-input-send" disabled="@string.IsNullOrWhiteSpace(Text)"
            @onclick="Send">
        @ButtonLabel
    </button>
</div>

@code {
    [Parameter] public string Placeholder { get; set; } = "Type a message…";
    [Parameter] public string ButtonLabel { get; set; } = "Send";
    [Parameter, EditorRequired] public EventCallback<string> OnSend { get; set; }

    private string Text { get; set; } = "";

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await Send();
        }
    }

    private async Task Send()
    {
        if (string.IsNullOrWhiteSpace(Text)) return;
        var content = Text.Trim();
        Text = "";
        await OnSend.InvokeAsync(content);
    }
}
