@using sv_8091738486b74e798f1f85cff83429c3.Models

<div class="message-bubble" @onmouseenter="() => _hovered = true" @onmouseleave="() => _hovered = false">
    <div class="message-bubble-header">
        <span class="message-bubble-author">@Message.Author</span>
        <span class="message-bubble-time" title="@Message.SentAt.ToString("f")">@FormatRelativeTime(Message.SentAt)</span>
    </div>
    <div class="message-bubble-content">@Message.Content</div>

    @if (Message.Reactions.Count > 0 || _hovered)
    {
        <ReactionBar Reactions="Message.Reactions" OnReact="HandleReact" />
    }

    @if (ReplyCount > 0)
    {
        <button type="button" class="message-thread-link" @onclick="OpenThread">
            💬 @ReplyCount @(ReplyCount == 1 ? "reply" : "replies")
        </button>
    }

    @if (_hovered)
    {
        <div class="message-actions">
            <button type="button" class="message-action-btn" @onclick="OpenThread" title="Reply in thread">💬 Reply</button>
            <button type="button" class="message-action-btn" @onclick="ToggleReactPicker" title="Add reaction">😀 React</button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public Message Message { get; set; } = default!;
    [Parameter] public int ReplyCount { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter, EditorRequired] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private bool _hovered;

    private async Task OpenThread() => await OnOpenThread.InvokeAsync(Message.Id);

    private void ToggleReactPicker()
    {
        // ReactionBar already handles the picker toggle; this is a convenience hover action
    }

    private async Task HandleReact(string emoji)
    {
        await OnReact.InvokeAsync((Message.Id, emoji));
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;
        if (diff.TotalSeconds < 60) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }
}

@using sv_8091738486b74e798f1f85cff83429c3.Models

<div class="channel-sidebar">
    <div class="channel-sidebar-header">
        <h5>Channels</h5>
    </div>
    <div class="channel-sidebar-list">
        @foreach (var channel in Channels)
        {
            <ChannelItem Channel="channel"
                         ActiveChannelId="ActiveChannelId"
                         OnSelected="OnChannelSelected" />
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<Channel> Channels { get; set; } = [];
    [Parameter] public int ActiveChannelId { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnChannelSelected { get; set; }
}

@using sv_8091738486b74e798f1f85cff83429c3.Models
@inject IJSRuntime JS

<div class="message-list" @ref="_listRef" @onscroll="HandleScroll">
    @if (IsLoadingOlder)
    {
        <div class="message-list-loading">Loading older messages…</div>
    }
    @foreach (var msg in Messages)
    {
        <MessageBubble Message="msg"
                       ReplyCount="GetReplyCount(msg.Id)"
                       OnOpenThread="OnOpenThread"
                       OnReact="OnReact" />
    }
</div>

@code {
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = new();
    [Parameter] public bool IsLoadingOlder { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter, EditorRequired] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter, EditorRequired] public EventCallback OnLoadOlder { get; set; }

    private ElementReference _listRef;

    private int GetReplyCount(int messageId) =>
        ThreadReplyCounts.TryGetValue(messageId, out var count) ? count : 0;

    private async Task HandleScroll()
    {
        var scrollTop = await JS.InvokeAsync<double>("eval", $"document.querySelector('.message-list')?.scrollTop ?? 1");
        if (scrollTop < 10 && !IsLoadingOlder)
        {
            await OnLoadOlder.InvokeAsync();
        }
    }
}

