}

@using sv_8091738486b74e798f1f85cff83429c3.Models
@inject IJSRuntime JS

<div class="message-list" @ref="_listRef" @onscroll="HandleScroll">
    @if (IsLoadingOlder)
    {
        <div class="message-list-loading">Loading older messages…</div>
    }
    @foreach (var msg in Messages)
    {
        <MessageBubble Message="msg"
                       ReplyCount="GetReplyCount(msg.Id)"
                       OnOpenThread="OnOpenThread"
                       OnReact="OnReact" />
    }
</div>

@code {
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = new();
    [Parameter] public bool IsLoadingOlder { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter, EditorRequired] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter, EditorRequired] public EventCallback OnLoadOlder { get; set; }

    private ElementReference _listRef;

    private int GetReplyCount(int messageId) =>
        ThreadReplyCounts.TryGetValue(messageId, out var count) ? count : 0;

    private async Task HandleScroll()
    {
        var scrollTop = await JS.InvokeAsync<double>("eval", $"document.querySelector('.message-list')?.scrollTop ?? 1");
        if (scrollTop < 10 && !IsLoadingOlder)
        {
            await OnLoadOlder.InvokeAsync();
        }
    }
}

