/* ==================== Chat Layout ==================== */
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    background: #1e1e2e;
    color: #cdd6f4;
    font-family: 'Segoe UI', system-ui, sans-serif;
}

.chat-placeholder {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    color: #6c7086;
    font-size: 1.1rem;
}

/* ==================== Channel Sidebar ==================== */
.channel-sidebar {
    width: 240px;
    min-width: 240px;
    background: #181825;
    border-right: 1px solid #313244;
    display: flex;
    flex-direction: column;
}

.channel-sidebar-header {
    padding: 16px;
    border-bottom: 1px solid #313244;
}

.channel-sidebar-header h5 {
    margin: 0;
    color: #cdd6f4;
    font-size: 1rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.channel-sidebar-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

/* ==================== Channel Item ==================== */
.channel-item {
    padding: 8px 16px;
    cursor: pointer;
    border-radius: 6px;
    margin: 2px 8px;
    transition: background 0.15s;
}

.channel-item:hover {
    background: #313244;
}

.channel-item--active {
    background: #45475a;
}

.channel-item-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.channel-item-name {
    font-weight: 600;
    font-size: 0.9rem;
    color: #cdd6f4;
}

.channel-item-badge {
    background: #f38ba8;
    color: #1e1e2e;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 1px 7px;
    border-radius: 10px;
    min-width: 20px;
    text-align: center;
}

.channel-item-desc {
    font-size: 0.75rem;
    color: #6c7086;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    margin-top: 2px;
}

/* ==================== Main Area ==================== */
.chat-main {
    flex: 1;
    min-width: 0;
    display: flex;
}

.chat-main--with-thread {
    /* When thread panel is open, main area shrinks */
}

.message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
}

.message-area-header {
    padding: 12px 20px;
    border-bottom: 1px solid #313244;
    background: #1e1e2e;
