    overflow-y: auto;
    padding: 16px 20px;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.message-list-loading {
    text-align: center;
    padding: 12px;
    color: #6c7086;
    font-size: 0.85rem;
