using sv_8091738486b74e798f1f85cff83429c3.Models;

namespace sv_8091738486b74e798f1f85cff83429c3.Services;

/// <summary>
/// In-memory stub implementation of IChatService for development/testing.
/// Replace with a real implementation backed by a database or API.
/// </summary>
public class InMemoryChatService : IChatService
{
    private readonly List<Channel> _channels;
    private readonly List<Message> _messages;
    private int _nextMessageId;

    public InMemoryChatService()
    {
        _channels =
        [
            new(1, "general", "General discussion for the team", 3),
            new(2, "engineering", "Engineering updates, PRs, and tech talk", 0),
            new(3, "random", "Off-topic conversations and fun stuff", 1),
            new(4, "announcements", "Important team announcements", 0),
        ];

        _messages =
        [
            new(1, 1, "Alice", "Hey everyone! Welcome to the new chat app 🎉", DateTime.UtcNow.AddHours(-3), null, [new("🎉", ["Bob", "Carol"])]),
            new(2, 1, "Bob", "Looks great! Love the dark theme.", DateTime.UtcNow.AddHours(-2.5), null, [new("👍", ["Alice"])]),
            new(3, 1, "Carol", "Thanks for setting this up. Any plans for file sharing?", DateTime.UtcNow.AddHours(-2), null, []),
            new(4, 1, "Alice", "Yes! It's on the roadmap for next sprint.", DateTime.UtcNow.AddMinutes(-90), 3, []),
            new(5, 1, "Dave", "Can't wait. Also, has anyone seen the new CI pipeline?", DateTime.UtcNow.AddMinutes(-45), null, [new("👍", ["Alice", "Bob"]), new("🚀", ["Carol"])]),
            new(6, 1, "Bob", "Yeah the new pipeline is way faster!", DateTime.UtcNow.AddMinutes(-30), 5, []),
            new(7, 2, "Eve", "PR #142 is ready for review — refactored the auth module.", DateTime.UtcNow.AddHours(-1), null, [new("👍", ["Frank"])]),
            new(8, 2, "Frank", "On it! Will review this afternoon.", DateTime.UtcNow.AddMinutes(-40), 7, []),
            new(9, 3, "Dave", "Anyone up for lunch today? 🍕", DateTime.UtcNow.AddMinutes(-20), null, [new("🎉", ["Alice"]), new("😂", ["Bob"])]),
        ];

        _nextMessageId = 10;
    }

    public Task<List<Channel>> GetChannelsAsync() =>
        Task.FromResult(_channels.ToList());

    public Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take) =>
        Task.FromResult(
            _messages
                .Where(m => m.ChannelId == channelId)
                .OrderBy(m => m.SentAt)
                .Skip(skip)
                .Take(take)
                .ToList());

    public Task<Message> SendMessageAsync(int channelId, string content, int? replyToId)
    {
        var msg = new Message(
            _nextMessageId++,
            channelId,
            "You",
            content,
            DateTime.UtcNow,
            replyToId,
            []);
        _messages.Add(msg);
        return Task.FromResult(msg);
    }

    public Task<List<Message>> GetThreadAsync(int rootMessageId) =>
        Task.FromResult(
            _messages
                .Where(m => m.ReplyToId == rootMessageId)
                .OrderBy(m => m.SentAt)
                .ToList());

    public Task AddReactionAsync(int messageId, string emoji) =>
        Task.CompletedTask;

    public Task MarkChannelReadAsync(int channelId)
    {
        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            _channels[idx] = _channels[idx] with { UnreadCount = 0 };
        }
        return Task.CompletedTask;
    }
}

